void ACLSelectorIngestRuntimeView(user *u, int kind, const char *payload, size_t len) {
    aclSelector *selector;
    if (u == NULL || u->selectors == NULL) return;
    if (listLength(u->selectors) == 0) return;
    selector = ACLUserGetRootSelector(u);
    if (kind == ACL_SELECTOR_VIEW_KEY) {
        ACLSelectorApplyKeyPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_NOTIFY) {
        ACLSelectorApplyKeyPolicy(selector, payload, len);
        ACLSelectorApplyChannelPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_CHANNEL) {
        ACLSelectorApplyChannelPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_BLOCK) {
        ACLSelectorApplyBlockPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_TIMEOUT) {
        ACLSelectorApplyTimeoutPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_RULE) {
        ACLSelectorApplyRulePolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_AUTH) {
        ACLSelectorApplyAuthPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_COMMAND) {
        ACLSelectorApplyCommandPolicy(selector, payload, len);
    } else if (kind == ACL_SELECTOR_VIEW_CONFIG) {
        ACLSelectorApplyConfigPolicy(selector, payload, len);
    }
}

